public class Main {
    static int sumIter(java.util.List<Integer> xs) {
        int sum = 0;
        java.util.Iterator<Integer> it = xs.iterator();
        while (it.hasNext()) sum += it.next();
        return sum;
    }
    public static void main(String[] args) {
        System.out.println(sumIter(java.util.List.of(2, 3)));
    }
}

