public class Main {
    static java.util.List<String> distinctInOrder(java.util.List<String> xs) {
        java.util.Set<String> seen = new java.util.LinkedHashSet<>(xs);
        return new java.util.ArrayList<>(seen);
    }
    public static void main(String[] args) {
        System.out.println(distinctInOrder(java.util.List.of("b", "a", "b")));
    }
}
